import sys, heapq
def solve(V,P,M):
    N=len(V)
    if M>N: return 0
    if M==1:
        return sum(max(0,V[i]-P[i]) for i in range(N))
    idx=sorted(range(N),key=lambda i:V[i])
    v=[V[i] for i in idx]; p=[P[i] for i in idx]
    pre=[0]*(N+1)
    for i in range(N): pre[i+1]=pre[i]+max(0,v[i]-p[i])
    cap=M-2
    best=0
    heap=[]; hs=0
    for i in range(N-1,-1,-1):
        if len(heap)==cap:
            c=pre[i]+(1-p[i])+hs
            if c>best: best=c
        if cap>0:
            w=1-p[i]
            heapq.heappush(heap,w); hs+=w
            if len(heap)>cap:
                hs-=heapq.heappop(heap)
    return best
def main():
    data=sys.stdin.buffer.read().split()
    t=int(data[0]); pos=1; out=[]
    for _ in range(t):
        n=int(data[pos]); m=int(data[pos+1]); pos+=2
        V=[0]*n; P=[0]*n
        for i in range(n):
            V[i]=int(data[pos]); P[i]=int(data[pos+1]); pos+=2
        out.append(str(solve(V,P,m)))
    sys.stdout.write("\n".join(out)+"\n")
