import sys

def fast(N, A):
    A = [0] + A
    prev = [0]*(N+2); last = {}
    for i in range(1, N+1):
        prev[i] = last.get(A[i], 0); last[A[i]] = i
    L = [0]*(N+2); seen = set()
    for i in range(1, N+1):
        seen.add(A[i]); L[i] = len(seen)
    R = [0]*(N+3); seen = set()
    for j in range(N, 0, -1):
        seen.add(A[j]); R[j] = len(seen)
    par = list(range(N+3)); par[1] = 2
    prv = [0]*(N+2); g = [0]*(N+2)
    head = tail = 0; maxv = lastv = 0
    best = 0
    for j in range(1, N):
        if j >= 2:
            base = L[j-1]
            while tail and lastv <= base:
                x = tail; p = prv[x]
                par[x] = x+1
                if p == 0:
                    tail = 0; head = 0
                    break
                lastv = g[x] + lastv
                tail = p
            if tail == 0:
                head = tail = j; maxv = lastv = base; prv[j] = 0
            else:
                g[j] = lastv - base; prv[j] = tail; tail = j; lastv = base
        if tail:
            a = prev[j] + 1
            k = a
            while par[k] != k:
                k = par[k]
            r = a
            while par[r] != k:
                par[r], r = k, par[r]
            lastv += 1
            if k == head:
                maxv += 1
            else:
                g[k] -= 1
                if g[k] == 0:
                    x = prv[k]; par[x] = x+1
                    p = prv[x]
                    if p == 0:
                        head = k; prv[k] = 0
                    else:
                        g[k] = g[x]; prv[k] = p
        if j >= 2:
            c = maxv + R[j+1]
            if c > best: best = c
    return best

