class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        N = len(s)
        steps = [0] * (N + 2)
        for v in range(2, N + 2):
            steps[v] = 1 + steps[bin(v).count('1')]
        C = [[0] * (N + 2) for _ in range(N + 2)]
        for a in range(N + 2):
            C[a][0] = 1
            for b in range(1, a + 1):
                C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD
        cnt = [0] * (N + 2)
        p = 0
        for i, ch in enumerate(s):
            if ch == '1':
                L = N - i - 1
                for r in range(L + 1):
                    cnt[p + r] = (cnt[p + r] + C[L][r]) % MOD
                p += 1
        ans = 0
        for c in range(1, N + 1):
            if steps[c] <= k - 1:
                ans = (ans + cnt[c]) % MOD
        return ans

