from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        N = n + 2; M = m + 2
        val = [-1] * (N * M)
        for i in range(n):
            for j in range(m):
                val[(i + 1) * M + j + 1] = grid[i][j]
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order
        G = [[None] * 4 for _ in range(2)]
        for t in range(2):
            for d in range(4):
                dr, dc = dirs[d]
                nd = (d + 1) % 4
                ndr, ndc = dirs[nd]
                off_s = dr * M + dc
                off_t = ndr * M + ndc
                g = [0] * (N * M)
                rows = range(1, n + 1) if dr <= 0 else range(n, 0, -1)
                cols = range(1, m + 1) if dc <= 0 else range(m, 0, -1)
                if dr == 0:
                    rows = range(1, n + 1)
                for r in rows:
                    base = r * M
                    for c in cols:
                        idx = base + c
                        v = val[idx]
                        if v != 0 and v != 2:
                            continue
                        exp = 2 if v == 0 else 0
                        best = 0
                        if val[idx + off_s] == exp:
                            best = g[idx + off_s]
                        if t == 1 and val[idx + off_t] == exp:
                            x = G[0][nd][idx + off_t]
                            if x > best:
                                best = x
                        g[idx] = 1 + best
                G[t][d] = g
        ans = 0
        for r in range(1, n + 1):
            for c in range(1, m + 1):
                idx = r * M + c
                if val[idx] == 1:
                    if ans < 1:
                        ans = 1
                    for d in range(4):
                        dr, dc = dirs[d]
                        nidx = idx + dr * M + dc
                        if val[nidx] == 2:
                            ans = max(ans, 1 + G[1][d][nidx])
        return ans

