from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def g(o, e, last):
            # number of alternating arrangements of o odd and e even values, last: 0 even, 1 odd, 2 none
            if o == 0 and e == 0:
                return 1
            res = 0
            if last != 1 and o > 0:
                res += o * g(o - 1, e, 1)
            if last != 0 and e > 0:
                res += e * g(o, e - 1, 0)
            return res

        o = (n + 1) // 2
        e = n // 2
        if g(o, e, 2) < k:
            return []
        rem = set(range(1, n + 1))
        res = []
        last = 2
        for _ in range(n):
            for v in sorted(rem):
                p = v & 1
                if last != 2 and p == last:
                    continue
                no = sum(1 for x in rem if x & 1) - (1 if p == 1 else 0)
                ne = sum(1 for x in rem if not x & 1) - (1 if p == 0 else 0)
                cnt = g(no, ne, p)
                if k <= cnt:
                    res.append(v)
                    rem.remove(v)
                    last = p
                    break
                k -= cnt
        return res

