        e = n // 2
        if g(o, e, 2) < k:
            return []
        rem = set(range(1, n + 1))
        res = []
        last = 2
        for _ in range(n):
            for v in sorted(rem):
                p = v & 1
                if last != 2 and p == last:
                    continue
                no = sum(1 for x in rem if x & 1) - (1 if p == 1 else 0)
                ne = sum(1 for x in rem if not x & 1) - (1 if p == 0 else 0)
                cnt = g(no, ne, p)
                if k <= cnt:
                    res.append(v)
                    rem.remove(v)
                    last = p
                    break
