class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [0] * n
        pw[0] = 1 % k
        for i in range(1, n):
            pw[i] = pw[i - 1] * 10 % k
        w = [0] * h
        for p in range(h):
            q = n - 1 - p
            w[p] = pw[p] if p == q else (pw[p] + pw[q]) % k
        R = [None] * (h + 1)
        R[h] = {0}
        for i in range(h - 1, -1, -1):
            s = set()
            for x in R[i + 1]:
                for d in range(10):
                    s.add((x + d * w[i]) % k)
            R[i] = s
        digits = []
        r = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (r + d * w[i]) % k
                if (-nr) % k in R[i + 1]:
                    digits.append(str(d))
                    r = nr
                    break
        first = ''.join(digits)
        rest = first[:n // 2][::-1]
        return first + rest

