class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        P = [0]*(n+1)
        for i, x in enumerate(nums):
            P[i+1] = P[i] + x
        vals = []; sts = []; ste = []; cb = []
        ans = 0
        for l in range(n-1, -1, -1):
            a = nums[l]
            e = l
            while vals and vals[-1] <= a:
                vals.pop(); sts.pop(); e = ste.pop(); cb.pop()
            prev = cb[-1] if cb else 0
            vals.append(a); sts.append(l); ste.append(e)
            cb.append(prev + a*(e-l+1))
            top = len(vals)-1
            Total = cb[top]
            def cost_end(t):
                e_ = ste[t]
                before = Total - (cb[t-1] if t > 0 else 0)
                return before - (P[e_+1]-P[l])
            if cost_end(0) <= k:
                r = n-1
            else:
                lo, hi = 0, top
                while lo < hi:
                    mid = (lo+hi+1)//2
                    if cost_end(mid) > k:
                        lo = mid
                    else:
                        hi = mid-1
                t1 = lo
                s = sts[t1]; ee = ste[t1]; v = vals[t1]
                base = Total - cb[t1]
                def cost(r_):
                    return base + v*(r_-s+1) - (P[r_+1]-P[l])
                lo, hi = s-1, ee
                while lo < hi:
                    mid = (lo+hi+1)//2
                    if cost(mid) <= k:
                        lo = mid
                    else:
                        hi = mid-1
                r = lo
            ans += r-l+1
        return ans

