import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def occ_kmp(s, x):
            m = len(x)
            if m == 0:
                return list(range(len(s) + 1))
            pi = [0] * m
            k = 0
            for q in range(1, m):
                while k and x[q] != x[k]:
                    k = pi[k - 1]
                if x[q] == x[k]:
                    k += 1
                pi[q] = k
            res = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != x[k]:
                    k = pi[k - 1]
                if ch == x[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = pi[k - 1]
            return res

        a, b, c = p.split('*')
        A, B, C = occ_kmp(s, a), occ_kmp(s, b), occ_kmp(s, c)
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for i in A:
            t = bisect.bisect_left(B, i + la)
            if t == len(B):
                continue
            j = B[t]
            u = bisect.bisect_left(C, j + lb)
            if u == len(C):
                continue
            L = C[u] + lc - i
            if best < 0 or L < best:
                best = L
        return best

