import re, bisect, random
class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        def occ(x):
            return [m.start() for m in re.finditer('(?=' + re.escape(x) + ')', s)]
        A, B, C = occ(a), occ(b), occ(c)
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for i in A:
            t = bisect.bisect_left(B, i + la)
            if t == len(B):
                continue
            j = B[t]
            u = bisect.bisect_left(C, j + lb)
            if u == len(C):
                continue
            k = C[u]
            L = k + lc - i
            if best < 0 or L < best:
                best = L
        return best

def brute(s, p):
    a, b, c = p.split('*')
    n = len(s); best = -1
    for i in range(n+1):
        for e in range(i, n+1):
            t = s[i:e]
            # match a*b*c as whole
            if len(t) < len(a)+len(b)+len(c): continue
            if t.startswith(a) and t.endswith(c):
                mid = t[len(a):len(t)-len(c)] if len(c) else t[len(a):]
                if b in mid:
                    if best < 0 or len(t) < best: best = len(t)
    return best

