class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        size = [1] * n
        order = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
                continue
            stack.append((x, True))
            for c in reversed(children[x]):
                stack.append((c, False))
        pos = [0] * n
        for idx, x in enumerate(order):
            pos[x] = idx
        for x in order:
            if parent[x] != -1:
                size[parent[x]] += size[x]
        T = [s[x] for x in order]
        MOD = (1 << 61) - 1
        B = random.randrange(10**5, 10**9)
        def build(arr):
            H = [0] * (n + 1)
            for i, ch in enumerate(arr):
                H[i + 1] = (H[i] * B + ord(ch)) % MOD
            return H
        P = [1] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] * B % MOD
        HF = build(T)
        HR = build(T[::-1])
        def get(H, l, r):
            return (H[r] - H[l] * P[r - l]) % MOD
        ans = [False] * n
        for x in range(n):
            r = pos[x] + 1
            l = r - size[x]
            ans[x] = get(HF, l, r) == get(HR, n - r, n - l)
        return ans

