def fast(n, a):
    seen=set(); L=[0]*(n+1)
    for i in range(n):
        seen.add(a[i]); L[i+1]=len(seen)
    seen=set(); R=[0]*(n+1)
    for i in range(n-1,-1,-1):
        seen.add(a[i]); R[i]=len(seen)
