class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        reach = [1] * n  # bit s set => sum s achievable for index j
        def ok():
            return all((reach[j] >> nums[j]) & 1 for j in range(n))
        if ok():
            return 0
        for k, (l, r, v) in enumerate(queries, 1):
            for j in range(l, r + 1):
                reach[j] |= reach[j] << v
            if ok():
                return k
        return -1

