class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        runs = []
        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j
        total = s.count('1')
        best = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                # neighbors are zero runs necessarily
                best = max(best, runs[k - 1][1] + runs[k + 1][1])
        return total + best

