def brute(s):
    n = len(s)
    marked = [False]*n
    score = 0
    for i in range(n):
        for j in range(i-1, -1, -1):
            if not marked[j] and not marked[i] and ord(s[j]) + ord(s[i]) == 2*97+25:
                marked[i] = marked[j] = True
                score += i - j
                break
    return score

