def brute(word, k):
    cnt = 0
    for i in range(len(word)):
        for j in range(i+1, len(word)+1):
            s = word[i:j]
            v = set(c for c in s if c in "aeiou")
            cons = sum(1 for c in s if c not in "aeiou")
            if len(v) == 5 and cons == k:
                cnt += 1
    return cnt

