from typing import List
class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo, hi = -10**19, 10**19
        base = original[0]
        for i, (u, v) in enumerate(bounds):
            off = original[i] - base
            lo = max(lo, u - off)
            hi = min(hi, v - off)
        return max(0, hi - lo + 1)
